
const TWOSIX_REMOTE_STANDALONE_B64="";
const LITEWORKSUITE_WEB_B64="";
function openRemoteStandalone(){
  try {
    const bin=atob(TWOSIX_REMOTE_STANDALONE_B64);
    const bytes=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
    let html=new TextDecoder("utf-8").decode(bytes);
    const base=location.protocol==="file:"?new URL("web/",location.href).href:new URL("./",location.href).href;
    html=html.replace("<head>",`<head><base href="${base}">`);
    const url=URL.createObjectURL(new Blob([html],{type:"text/html;charset=utf-8"}));
    location.href=url;
  } catch(e) {
    alert("Não foi possível abrir o Native Remote: "+e.message);
  }
}

