function bytesHex(buf){return [...new Uint8Array(buf)].map(x=>x.toString(16).padStart(2,"0")).join("")}
function hexBytes(hex){const a=new Uint8Array(hex.length/2);for(let i=0;i<a.length;i++)a[i]=parseInt(hex.substr(i*2,2),16);return a}
async function makePinHash(pin){if(!pin)return"";if(!crypto?.subtle)return"legacy$"+btoa(pin);const salt=crypto.getRandomValues(new Uint8Array(16)),iter=160000,base=await crypto.subtle.importKey("raw",new TextEncoder().encode(pin),"PBKDF2",false,["deriveBits"]),bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt,iterations:iter,hash:"SHA-256"},base,256);return `pbkdf2$${iter}$${bytesHex(salt)}$${bytesHex(bits)}`}
async function verifyPin(pin,stored){if(!stored)return true;if(stored.startsWith("pbkdf2$")){if(!crypto?.subtle)return false;const p=stored.split("$"),iter=Number(p[1]),salt=hexBytes(p[2]),base=await crypto.subtle.importKey("raw",new TextEncoder().encode(pin),"PBKDF2",false,["deriveBits"]),bits=bytesHex(await crypto.subtle.deriveBits({name:"PBKDF2",salt,iterations:iter,hash:"SHA-256"},base,256));return bits===p[3]}if(stored.startsWith("legacy$"))return stored==="legacy$"+btoa(pin);if(crypto?.subtle){const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(pin));return bytesHex(b)===stored}return btoa(pin)===stored}
async function api(path,opts={}){
 const headers={...(opts.headers||{})};
 if(sessionToken)headers["X-TwoSix-Token"]=sessionToken;
 const res=await fetch(path,{...opts,headers});
 if(!res.ok)throw new Error(await res.text());
 const ct=res.headers.get("content-type")||"";
 return ct.includes("application/json")?res.json():res.text();
}
