function wireWindow(w,id){w.onpointerdown=()=>focus(w);$$(".window-controls button",w).forEach(b=>b.onclick=()=>{if(b.dataset.act==="close")closeWindow(id);if(b.dataset.act==="min")w.hidden=true;if(b.dataset.act==="max")w.classList.toggle("max")});const bar=$(".window-bar",w);let drag=null;bar.onpointerdown=e=>{if(w.classList.contains("max")||e.target.closest("button")||matchMedia("(max-width:720px)").matches)return;const r=w.getBoundingClientRect();drag={dx:e.clientX-r.left,dy:e.clientY-r.top};bar.setPointerCapture(e.pointerId)};bar.onpointermove=e=>{if(!drag)return;w.style.left=Math.max(0,e.clientX-drag.dx)+"px";w.style.top=Math.max(0,e.clientY-drag.dy-44)+"px"};bar.onpointerup=()=>drag=null}
