function uuid(){return (crypto.randomUUID?.()||("f"+Date.now()+Math.random()).replace(".",""))}
function activeFiles(){return state.files.filter(f=>!f.deleted).sort((a,b)=>(b.updated||0)-(a.updated||0))}
function saveFileObj(file){const now=Date.now();if(file.id){const old=state.files.find(x=>x.id===file.id);if(old){old.versions=old.versions||[];old.versions.push({time:old.updated,content:old.content});old.versions=old.versions.slice(-10);Object.assign(old,file,{updated:now,deleted:false});saveState();return old.id}}file.id=uuid();file.created=now;file.updated=now;file.deleted=false;file.versions=[];state.files.push(file);saveState();return file.id}
function filesApp(){const r=wrap(`<div class="toolbar"><button data-new>＋ Novo texto</button><button data-refresh>↻ Atualizar</button></div><div class="panel"><div class="card"><table class="files-table"><thead><tr><th>Nome</th><th>Tipo</th><th>Versões</th><th>Alterado</th><th>Ações</th></tr></thead><tbody></tbody></table></div></div>`),tb=$("tbody",r);function refresh(){tb.innerHTML="";const fs=activeFiles();if(!fs.length){tb.innerHTML='<tr><td colspan="5" class="muted">Nenhum documento salvo.</td></tr>';return}fs.forEach(f=>{const tr=document.createElement("tr");tr.innerHTML=`<td>${esc(f.name)}</td><td>${esc(f.type)}</td><td><span class="badge">${(f.versions||[]).length}</span></td><td>${new Date(f.updated).toLocaleString("pt-BR")}</td><td><button data-o>Abrir</button> <button data-d>Lixeira</button></td>`;$("[data-o]",tr).onclick=()=>openStored(f);$("[data-d]",tr).onclick=()=>{if(confirm("Mover para a lixeira?")){f.deleted=true;f.deletedAt=Date.now();saveState();refresh()}};tb.appendChild(tr)})}$("[data-new]",r).onclick=()=>openApp("writer");$("[data-refresh]",r).onclick=refresh;refresh();return r}

/* ===== TwoSix 5.1 Drive ===== */
const TSD_DB="TwoSixDrive28",TSD_STORE="entries";
let tsdDbP=null;
function tsdOpen(){
 if(tsdDbP)return tsdDbP;
 tsdDbP=new Promise((resolve,reject)=>{
   const r=indexedDB.open(TSD_DB,1);
   r.onupgradeneeded=()=>{
     const db=r.result;
     if(!db.objectStoreNames.contains(TSD_STORE)){
       const s=db.createObjectStore(TSD_STORE,{keyPath:"id"});
       s.createIndex("parent","parent",{unique:false});
       s.createIndex("deleted","deleted",{unique:false});
     }
   };
   r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);
 });
 return tsdDbP;
}
async function tsdAll(){
 const db=await tsdOpen();
 return new Promise((resolve,reject)=>{const r=db.transaction(TSD_STORE).objectStore(TSD_STORE).getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)});
}
async function tsdPut(e){
 const db=await tsdOpen();e.updated=Date.now();if(!e.created)e.created=e.updated;
 return new Promise((resolve,reject)=>{const tx=db.transaction(TSD_STORE,"readwrite");tx.objectStore(TSD_STORE).put(e);tx.oncomplete=()=>resolve(e);tx.onerror=()=>reject(tx.error)});
}
async function tsdGet(id){
 const db=await tsdOpen();
 return new Promise((resolve,reject)=>{const r=db.transaction(TSD_STORE).objectStore(TSD_STORE).get(id);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)});
}
async function tsdHardDelete(id){
 const db=await tsdOpen();
 return new Promise((resolve,reject)=>{const tx=db.transaction(TSD_STORE,"readwrite");tx.objectStore(TSD_STORE).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});
}
function tsdId(){return crypto.randomUUID?.()||("d"+Date.now()+Math.random().toString(16).slice(2))}
function tsdFmt(n){n=Number(n)||0;if(n<1024)return n+" B";if(n<1048576)return(n/1024).toFixed(1)+" KB";if(n<1073741824)return(n/1048576).toFixed(1)+" MB";return(n/1073741824).toFixed(2)+" GB"}
function tsdIcon(e){
 if(e.kind==="folder")return"📁";const t=(e.type||"").toLowerCase(),n=(e.name||"").toLowerCase();
 if(t.includes("pdf")||n.endsWith(".pdf"))return"📕";if(t.startsWith("image/"))return"🖼️";if(t.startsWith("video/"))return"🎬";if(t.startsWith("audio/"))return"🎵";
 if(/\.(doc|docx|odt|rtf|txt|html?)$/.test(n))return"📄";if(/\.(xls|xlsx|ods|csv)$/.test(n))return"📊";if(/\.(ppt|pptx|odp)$/.test(n))return"📽️";if(/\.(zip|rar|7z|tar|gz)$/.test(n))return"🗜️";return"📦"
}
async function tsdEnsureFolders(){
 const all=await tsdAll();if(all.some(x=>x.seedFolder))return;
 for(const name of["Documentos","Planilhas","Apresentações","PDFs","Imagens","Mídia","Downloads","Compartilhados"]){
   await tsdPut({id:tsdId(),kind:"folder",name,parent:"root",deleted:false,seedFolder:true});
 }
}
async function tsdSaveBlob(name,blob,parent="root",type=""){
 return tsdPut({id:tsdId(),kind:"file",name,parent,type:type||blob.type||"application/octet-stream",size:blob.size||0,blob,deleted:false});
}

