window.addEventListener("message",async e=>{
 const d=e.data||{};
 if(d.type!=="liteworksuite-drive-save")return;
 try{
   if(!(d.blob instanceof Blob))throw new Error("Conteúdo inválido.");
   await tsdEnsureFolders();
   const all=await tsdAll();
   const ext=(d.name||"").toLowerCase();
   let targetName="Documentos";
   if(/\.(xlsx|xlsm|csv|tsv)$/.test(ext))targetName="Planilhas";
   else if(/\.(pptx|pptm)$/.test(ext))targetName="Apresentações";
   else if(/\.pdf$/.test(ext))targetName="PDFs";
   const folder=all.find(x=>x.kind==="folder"&&x.name===targetName&&!x.deleted);
   await tsdSaveBlob(String(d.name||"arquivo").slice(0,180),d.blob,folder?.id||"root",d.mime||d.blob.type);
   try{e.source?.postMessage({type:"twosix-drive-saved",name:d.name},"*")}catch{}
 }catch(err){
   try{e.source?.postMessage({type:"twosix-drive-error",error:err.message},"*")}catch{}
 }
});

async function tsdDownloadEntry(e){
 if(!e?.blob)return alert("Este item não contém arquivo binário.");
 const u=URL.createObjectURL(e.blob),a=document.createElement("a");a.href=u;a.download=e.name;a.click();setTimeout(()=>URL.revokeObjectURL(u),800)
}
async function tsdShareEntry(e){
 if(!e?.blob)return;
 const f=new File([e.blob],e.name,{type:e.type||e.blob.type});
 if(navigator.canShare?.({files:[f]})){try{await navigator.share({files:[f],title:e.name})}catch{}}
 else tsdDownloadEntry(e);
}
async function tsdPreview(e){
 if(!e?.blob)return;
 const u=URL.createObjectURL(e.blob),t=e.type||"",n=e.name.toLowerCase();let inner="";
 if(t.startsWith("image/"))inner=`<img src="${u}" alt="">`;
 else if(t.startsWith("video/"))inner=`<video controls autoplay src="${u}"></video>`;
 else if(t.startsWith("audio/"))inner=`<audio controls autoplay src="${u}"></audio>`;
 else if(t.includes("pdf")||n.endsWith(".pdf"))inner=`<iframe src="${u}"></iframe>`;
 else if(t.startsWith("text/")||/\.(txt|csv|md|json|html?)$/.test(n)){const txt=await e.blob.text();inner=`<pre>${esc(txt.slice(0,100000))}</pre>`}
 else {URL.revokeObjectURL(u);return tsdDownloadEntry(e)}
 const node=wrap(`<div class="toolbar"><button data-dl>Baixar</button><button data-share>Compartilhar</button></div><div class="panel"><h3>${esc(e.name)}</h3><div class="media-stage">${inner}</div></div>`);
 $("[data-dl]",node).onclick=()=>tsdDownloadEntry(e);$("[data-share]",node).onclick=()=>tsdShareEntry(e);
 openUtilityWindow("preview-"+e.id,"Visualizar • "+e.name,node,()=>URL.revokeObjectURL(u));
}
function openUtilityWindow(key,title,node,onClose){
 if(windows.has(key)){const w=windows.get(key);w.hidden=false;focus(w);return}
 const w=$("#windowTemplate").content.firstElementChild.cloneNode(true);w.dataset.app=key;w.style.zIndex=++z;$(".window-title",w).textContent=title;$(".window-body",w).appendChild(node);
 $("#windowLayer").appendChild(w);windows.set(key,w);wireWindow(w,key);taskButtonCustom(key,title);
 if(onClose)w._cleanup=onClose;focus(w)
}
function taskButtonCustom(id,title){const b=document.createElement("button");b.className="task-app";b.dataset.task=id;b.textContent=title;b.onclick=()=>{const w=windows.get(id);if(!w)return;w.hidden=!w.hidden;if(!w.hidden)focus(w)};$("#taskApps").appendChild(b)}
const _closeWindow28=closeWindow;
closeWindow=function(id){const w=windows.get(id);try{w?._cleanup?.()}catch{};_closeWindow28(id)};

function driveApp(){
 const r=wrap(`<div class="drive-shell">
 <div class="drive-toolbar">
   <button data-up>↑</button><button data-newfolder>＋ Pasta</button><button data-import>⇧ Importar</button><button data-trash>🗑 Lixeira</button>
   <input class="grow" data-search placeholder="Pesquisar no Drive...">
   <button data-persist>Fixar armazenamento</button>
   <input data-files type="file" multiple hidden>
 </div>
 <div class="drive-crumbs" data-crumbs>Disco TwoSix</div>
 <div class="drive-content" data-content><div class="drive-empty">Carregando TwoSix Drive...</div></div>
 </div>`);
 let parent="root",query="",trash=false;
 const content=$("[data-content]",r),crumbs=$("[data-crumbs]",r),input=$("[data-files]",r);
 async function pathNames(){
   if(parent==="root")return["Disco TwoSix"];const all=await tsdAll(),map=new Map(all.map(x=>[x.id,x])),arr=[];let cur=map.get(parent),guard=0;
   while(cur&&guard++<50){arr.unshift(cur.name);cur=map.get(cur.parent)}return["Disco TwoSix",...arr];
 }
 async function usage(){
   try{const est=await navigator.storage?.estimate?.();if(!est)return"";const pct=est.quota?Math.min(100,(est.usage/est.quota)*100):0;return `<div style="min-width:170px"><small>${tsdFmt(est.usage)} usados de ${tsdFmt(est.quota)}</small><div class="meter"><span style="width:${pct}%"></span></div></div>`}catch{return""}
 }
 async function refresh(){
   await tsdEnsureFolders();const all=await tsdAll(),paths=await pathNames();crumbs.innerHTML=paths.map(esc).join(" › ")+" "+await usage();
   let list=all.filter(x=>trash?x.deleted:(!x.deleted&&x.parent===parent));
   if(query){const q=query.toLowerCase();list=all.filter(x=>!x.deleted&&(x.name||"").toLowerCase().includes(q))}
   list.sort((a,b)=>(a.kind===b.kind?(a.name||"").localeCompare(b.name||""):(a.kind==="folder"?-1:1)));
   content.innerHTML="";
   if(!list.length){content.innerHTML=`<div class="drive-empty">${trash?"Lixeira do Drive vazia.":"Nenhum item aqui."}</div>`;return}
   const grid=document.createElement("div");grid.className="drive-grid";
   list.forEach(e=>{
     const c=document.createElement("div");c.className="drive-card";
     c.innerHTML=`<div class="ico">${tsdIcon(e)}</div><div class="fname">${esc(e.name)}</div><div class="fmeta">${e.kind==="folder"?"Pasta":`${esc(e.type||"arquivo")} • ${tsdFmt(e.size)}`}<br>${new Date(e.updated||e.created).toLocaleString("pt-BR")}</div><div class="factions"></div>`;
     const a=$(".factions",c),mk=(txt,fn)=>{const b=document.createElement("button");b.textContent=txt;b.onclick=ev=>{ev.stopPropagation();fn()};a.appendChild(b)};
     if(trash){
       mk("Restaurar",async()=>{e.deleted=false;delete e.deletedAt;await tsdPut(e);refresh()});
       mk("Excluir",async()=>{if(confirm("Excluir definitivamente?")){await tsdHardDelete(e.id);refresh()}});
     }else{
       if(e.kind==="file"){mk("Abrir",()=>tsdPreview(e));mk("Baixar",()=>tsdDownloadEntry(e));mk("Compartilhar",()=>tsdShareEntry(e))}
       mk("Renomear",async()=>{const n=(prompt("Novo nome:",e.name)||"").trim();if(n){e.name=n;await tsdPut(e);refresh()}});
       mk("Mover",async()=>{const folders=all.filter(x=>x.kind==="folder"&&!x.deleted&&x.id!==e.id);const options=["root",...folders.map(x=>x.id)],labels=["Disco TwoSix",...folders.map(x=>x.name)];const answer=(prompt("Destino:\\n"+labels.map((x,i)=>`${i}: ${x}`).join("\\n"),"0")||"").trim();const ix=Number(answer);if(Number.isInteger(ix)&&options[ix]){e.parent=options[ix];await tsdPut(e);refresh()}});
       mk("Lixeira",async()=>{e.deleted=true;e.deletedAt=Date.now();await tsdPut(e);refresh()});
     }
     c.onclick=()=>{if(e.kind==="folder"&&!trash){parent=e.id;query="";$("[data-search]",r).value="";refresh()}else if(e.kind==="file"&&!trash)tsdPreview(e)};
     grid.appendChild(c)
   });
   content.appendChild(grid)
 }
 $("[data-up]",r).onclick=async()=>{if(trash){trash=false;parent="root";return refresh()}if(parent==="root")return;const e=await tsdGet(parent);parent=e?.parent||"root";refresh()};
 $("[data-newfolder]",r).onclick=async()=>{const n=(prompt("Nome da pasta:","Nova pasta")||"").trim();if(n){await tsdPut({id:tsdId(),kind:"folder",name:n,parent,deleted:false});refresh()}};
 $("[data-import]",r).onclick=()=>input.click();
 input.onchange=async()=>{for(const f of input.files)await tsdSaveBlob(f.name,f,parent,f.type);input.value="";refresh()};
 $("[data-search]",r).oninput=e=>{query=e.target.value.trim();trash=false;refresh()};
 $("[data-trash]",r).onclick=()=>{trash=!trash;query="";$("[data-search]",r).value="";refresh()};
 $("[data-persist]",r).onclick=async()=>{if(!navigator.storage?.persist)return alert("Persistência não disponível neste navegador.");const ok=await navigator.storage.persist();alert(ok?"Armazenamento persistente solicitado/ativo.":"O navegador não concedeu persistência.")};
 content.ondragover=e=>{e.preventDefault();content.classList.add("drive-drop")};content.ondragleave=()=>content.classList.remove("drive-drop");
 content.ondrop=async e=>{e.preventDefault();content.classList.remove("drive-drop");for(const f of e.dataTransfer.files)await tsdSaveBlob(f.name,f,parent,f.type);refresh()};
 refresh();return r
}

