function calculatorApp(){
 const r=wrap(`<div class="panel"><input class="calc-display" data-display value="0" inputmode="decimal"><div class="calc-pad"></div></div>`),d=$("[data-display]",r),pad=$(".calc-pad",r);
 const keys=["C","⌫","(",")","7","8","9","÷","4","5","6","×","1","2","3","−","0",".","=","+"];
 keys.forEach(k=>{const b=document.createElement("button");b.textContent=k;b.onclick=()=>{if(k==="C")d.value="0";else if(k==="⌫")d.value=d.value.length>1?d.value.slice(0,-1):"0";else if(k==="="){let ex=d.value.replaceAll("×","*").replaceAll("÷","/").replaceAll("−","-").replace(",",".");if(!/^[0-9+\-*/().\s]+$/.test(ex))return d.value="Erro";try{d.value=String(Function(`"use strict";return (${ex})`)())}catch{d.value="Erro"}}else{if(d.value==="0"||d.value==="Erro")d.value="";d.value+=k}};pad.appendChild(b)});
 return r
}
function calendarApp(){
 const r=wrap(`<div class="toolbar"><button data-prev>‹</button><b data-title></b><button data-next>›</button><button data-today>Hoje</button><button data-add>＋ Evento</button></div><div class="panel"><div class="calendar-grid" data-cal></div><hr style="border-color:var(--line)"><div data-events></div></div>`);
 let cur=new Date();cur.setDate(1);state.calendarEvents=Array.isArray(state.calendarEvents)?state.calendarEvents:[];
 function draw(){
   const title=cur.toLocaleDateString("pt-BR",{month:"long",year:"numeric"});$("[data-title]",r).textContent=title;
   const cal=$("[data-cal]",r);cal.innerHTML="";["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"].forEach(x=>{const h=document.createElement("div");h.className="cal-head";h.textContent=x;cal.appendChild(h)});
   for(let i=0;i<cur.getDay();i++)cal.appendChild(document.createElement("div"));
   const last=new Date(cur.getFullYear(),cur.getMonth()+1,0).getDate(),now=new Date();
   for(let n=1;n<=last;n++){const d=document.createElement("div");d.className="cal-day";if(n===now.getDate()&&cur.getMonth()===now.getMonth()&&cur.getFullYear()===now.getFullYear())d.classList.add("today");const iso=`${cur.getFullYear()}-${String(cur.getMonth()+1).padStart(2,"0")}-${String(n).padStart(2,"0")}`,evs=state.calendarEvents.filter(e=>e.date===iso);d.innerHTML=`<b>${n}</b>${evs.map(e=>`<div class="muted">• ${esc(e.title)}</div>`).join("")}`;d.onclick=()=>add(iso);cal.appendChild(d)}
   const host=$("[data-events]",r),monthly=state.calendarEvents.filter(e=>e.date.startsWith(`${cur.getFullYear()}-${String(cur.getMonth()+1).padStart(2,"0")}`)).sort((a,b)=>a.date.localeCompare(b.date));host.innerHTML=monthly.length?monthly.map(e=>`<p>${esc(e.date)} — <b>${esc(e.title)}</b></p>`).join(""):'<p class="muted">Sem eventos neste mês.</p>'
 }
 function add(date){const title=(prompt("Evento:")||"").trim();if(!title)return;state.calendarEvents.push({id:uuid(),date,title});saveState();draw()}
 $("[data-prev]",r).onclick=()=>{cur.setMonth(cur.getMonth()-1);draw()};$("[data-next]",r).onclick=()=>{cur.setMonth(cur.getMonth()+1);draw()};$("[data-today]",r).onclick=()=>{cur=new Date();cur.setDate(1);draw()};$("[data-add]",r).onclick=()=>add(new Date().toISOString().slice(0,10));draw();return r
}
function clockApp(){
 const r=wrap(`<div class="panel"><div class="big-clock" data-now></div><div class="utility-grid"><div class="card"><h3>Cronômetro</h3><div class="timer-display" data-sw>00:00.0</div><p><button data-swstart>Iniciar/Pausar</button> <button data-swreset>Zerar</button></p></div><div class="card"><h3>Timer</h3><input data-min type="number" min="0" value="5"> minutos <div class="timer-display" data-timer>05:00</div><p><button data-tstart>Iniciar/Pausar</button> <button data-treset>Reiniciar</button></p></div></div></div>`);
 let sw=0,swRun=false,last=performance.now(),timer=300,tRun=false;
 function fmt(s,tenths=false){const m=Math.floor(s/60),sec=Math.floor(s%60),t=Math.floor((s%1)*10);return `${String(m).padStart(2,"0")}:${String(sec).padStart(2,"0")}${tenths?"."+t:""}`}
 const iv=setInterval(()=>{const now=performance.now();if(swRun)sw+=(now-last)/1000;if(tRun){timer=Math.max(0,timer-(now-last)/1000);if(timer===0){tRun=false;try{navigator.vibrate?.([200,100,200])}catch{};alert("Timer concluído.")}}last=now;$("[data-now]",r).textContent=new Date().toLocaleTimeString("pt-BR");$("[data-sw]",r).textContent=fmt(sw,true);$("[data-timer]",r).textContent=fmt(timer)},100);
 r._cleanup=()=>clearInterval(iv);$("[data-swstart]",r).onclick=()=>swRun=!swRun;$("[data-swreset]",r).onclick=()=>{sw=0;swRun=false};$("[data-tstart]",r).onclick=()=>tRun=!tRun;$("[data-treset]",r).onclick=()=>{timer=Math.max(0,Number($("[data-min]",r).value)||0)*60;tRun=false};return r
}
