 $("[data-test]",r).onclick=async()=>{const out=$("[data-result]",r),t=performance.now();if(!/^https?:$/.test(location.protocol)){out.textContent="Teste HTTP indisponível quando aberto como arquivo local.";return}try{await fetch(location.href,{cache:"no-store",method:"GET"});out.textContent=`Origem respondeu em ~${Math.round(performance.now()-t)} ms.`}catch(e){out.textContent="Falha: "+e.message}};window.addEventListener("online",stateNet);window.addEventListener("offline",stateNet);stateNet();return r
