function trashApp(){const r=wrap(`<div class="toolbar"><button data-empty>Esvaziar lixeira</button></div><div class="panel"><div class="card"><table class="files-table"><thead><tr><th>Nome</th><th>Excluído</th><th>Ações</th></tr></thead><tbody></tbody></table></div></div>`),tb=$("tbody",r);function refresh(){tb.innerHTML="";const fs=state.files.filter(f=>f.deleted);if(!fs.length){tb.innerHTML='<tr><td colspan="3" class="muted">Lixeira vazia.</td></tr>';return}fs.forEach(f=>{const tr=document.createElement("tr");tr.innerHTML=`<td>${esc(f.name)}</td><td>${new Date(f.deletedAt||Date.now()).toLocaleString("pt-BR")}</td><td><button data-r>Restaurar</button> <button data-x>Excluir</button></td>`;$("[data-r]",tr).onclick=()=>{f.deleted=false;delete f.deletedAt;saveState();refresh()};$("[data-x]",tr).onclick=()=>{if(confirm("Excluir definitivamente?")){state.files=state.files.filter(x=>x.id!==f.id);saveState();refresh()}};tb.appendChild(tr)})}$("[data-empty]",r).onclick=()=>{if(confirm("Esvaziar lixeira?")){state.files=state.files.filter(f=>!f.deleted);saveState();refresh()}};refresh();return r}

function b64(bytes){let s="";for(const x of new Uint8Array(bytes))s+=String.fromCharCode(x);return btoa(s)}function unb64(s){const x=atob(s),a=new Uint8Array(x.length);for(let i=0;i<x.length;i++)a[i]=x.charCodeAt(i);return a}
async function deriveBackupKey(pass,salt,iter=220000){const raw=await crypto.subtle.importKey("raw",new TextEncoder().encode(pass),"PBKDF2",false,["deriveKey"]);return crypto.subtle.deriveKey({name:"PBKDF2",salt,iterations:iter,hash:"SHA-256"},raw,{name:"AES-GCM",length:256},false,["encrypt","decrypt"])}
async function encryptBackup(pass){if(!crypto?.subtle)throw new Error("Web Crypto indisponível");if(pass.length<8)throw new Error("Use senha com pelo menos 8 caracteres");const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),iter=220000,key=await deriveBackupKey(pass,salt,iter),plain=new TextEncoder().encode(JSON.stringify(state)),cipher=await crypto.subtle.encrypt({name:"AES-GCM",iv},key,plain);return JSON.stringify({format:"TwoSixEncryptedBackup",version:1,kdf:"PBKDF2-SHA256",iterations:iter,salt:b64(salt),iv:b64(iv),cipher:b64(cipher)})}
async function decryptBackup(text,pass){const o=JSON.parse(text);if(o.format!=="TwoSixEncryptedBackup")throw new Error("Formato inválido");const key=await deriveBackupKey(pass,unb64(o.salt),Number(o.iterations||220000)),plain=await crypto.subtle.decrypt({name:"AES-GCM",iv:unb64(o.iv)},key,unb64(o.cipher));return JSON.parse(new TextDecoder().decode(plain))}

function backupApp(){const r=wrap(`<div class="panel"><h2>Backup e restauração</h2><div class="settings-grid"><div class="setting"><h3>Backup criptografado</h3><p>Recomendado para dados pessoais/documentos.</p><input data-pass type="password" autocomplete="new-password" placeholder="Senha (mín. 8 caracteres)"><p><button data-enc>Baixar .tw6enc</button></p></div><div class="setting"><h3>Restaurar criptografado</h3><input data-restorepass type="password" autocomplete="off" placeholder="Senha do backup"><p><button data-encbtn>Selecionar .tw6enc</button><input data-encfile type="file" accept=".tw6enc,.json" hidden></p></div><div class="setting"><h3>JSON simples</h3><p class="muted">Use somente quando o conteúdo não for sensível.</p><button data-export>Baixar JSON</button> <button data-importbtn>Restaurar JSON</button><input data-import type="file" accept=".json" hidden></div><div class="setting"><h3>Armazenamento</h3><p class="${portable?"status-ok":"status-warn"}">${portable?"Modo USB persistente ativo.":"Fallback do navegador ativo."}</p></div></div></div>`);$("[data-enc]",r).onclick=async()=>{try{const p=$("[data-pass]",r).value;const out=await encryptBackup(p);download("twosix-5.1-backup.tw6enc",out,"application/json");$("[data-pass]",r).value=""}catch(e){alert(e.message)}};$("[data-encbtn]",r).onclick=()=>$("[data-encfile]",r).click();$("[data-encfile]",r).onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const x=await decryptBackup(await f.text(),$("[data-restorepass]",r).value);if(!x||typeof x!=="object"||!Array.isArray(x.files))throw new Error("Backup inválido");state=Object.assign(structuredClone(DEFAULT),x);saveState(true);alert("Backup restaurado. A página será recarregada.");location.reload()}catch(e){alert("Falha ao restaurar: "+e.message)}};$("[data-export]",r).onclick=()=>download("twosix-5.1-backup.json",JSON.stringify(state,null,2),"application/json");$("[data-importbtn]",r).onclick=()=>$("[data-import]",r).click();$("[data-import]",r).onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const x=JSON.parse(await f.text());if(!x||typeof x!=="object"||!Array.isArray(x.files))throw 0;state=Object.assign(structuredClone(DEFAULT),x);saveState(true);alert("Backup restaurado. A página será recarregada.");location.reload()}catch{alert("Backup inválido.")}};return r}

